/// <summary>
/// Display the full dimension value under 'History tab > fields value and previous value' instead of the RecID
/// </summary>
[ExtensionOf(formStr(SysDatabaseLog))]
final class METSysDatabaseLog_Extension
{
    #resAppl
    #define.overview(1)
    #define.history(2)
  
}

Method.Source:
    void buildContentsV2()
    {
        container       tmp;
        SysDataBaseLog  log;
        FormListItem    item,itemname,defname;
        fieldId         fieldId;
        int             i, idx;
        List            datalist;
        ListEnumerator  enumerator;

        next buildContentsV2();
    
        if (tab.tab() != #history)
            return;

        list.deleteAll();
    
        select log
            order by CreatedDateTime, RecId
            where log.Table             == sysDataBaseLog.Table &&
                  log.LogRecId          == sysDatabaseLog.LogRecId  &&
            log.RecId             == dbHistory.RecId;
        
        // if (DatabaseLogParameters::find().DatabaseLogArrayFields == NoYes::Yes)
        // {
        //     datalist = log.getDataAslistArrayFields();
        // }
        // else
        // {
        datalist = log.getDataAslist(true);
        //}
        enumerator = datalist.getEnumerator();
        while (enumerator.moveNext())
        {
            i++;
            tmp = enumerator.current();
            anytype valueContent;
            anytype oldValueContent;
            fieldId = conPeek(tmp, 1);
            [fieldId, valueContent, oldValueContent] = tmp;

            var value = sysdatabaselog.contents2Str(valueContent, fieldId);
            var oldValue = sysdatabaselog.contents2Str(conPeek(tmp, 3), fieldId);

            itemname    = new FormListItem(fieldId2name(log.table, fieldId));
            defname     = new FormListItem("LedgerDimension");

            if(itemname.text() == defname.text())
            {

                value       =  LedgerDynamicAccountHelper::getAccountNumberFromDynamicAccount(DimensionAttributeValueCombination::find(str2Int64(value)).RecId);
                oldValue    =  LedgerDynamicAccountHelper::getAccountNumberFromDynamicAccount(DimensionAttributeValueCombination::find(str2Int64(oldValue)).RecId);
          
            }
            else
            {
                value = value;
                oldValue = oldValue;
            }
            
            // If the field was stored as array field, we display the corresponding index
            if (conLen(tmp) >= 4 && conPeek(tmp, 4) == true)
            {
                str fName = fieldId2name(log.table, fieldId);
                fName = strFmt("%1 [%2]", fName, fieldExt2Idx(fieldId));
                item = new FormListItem(fName);
            }
            // Not stored as array field (either not an array field, or array field support was not enabled when saved in SysDatabaseLog)
            else
            {
                item = new FormListItem(fieldId2name(log.table, fieldId));
            }

            item.image(imagelist.image((oldValue) ? #ImageLogModified : #ImageLogBlank));
            idx = list.addItem(item);
    
            //BP Deviation Documented
            item = (value && log.LogType != DatabaseLogType::Delete) ? new FormListItem(value) : new FormListItem('');
            item.subItem(1);
            list.setItem(item);

            //BP Deviation Documented
            item = (oldValue && log.LogType != DatabaseLogType::Insert) ? new FormListItem(oldValue) : new FormListItem('');
            item.subItem(2);
            list.setItem(item);
        }
       
    }
